//! Native 1.2 evidence: x2game12.c 397B2350 reads i32 skillCount and tagCount,
//! each followed by (id, total, remaining) u32 triples; 39899D40 appends them,
//! 3989A290 selects the longest skill/tag timer, and 39899F90 never shortens a tag.
//! UI baselib.lua:346-383 consumes remaining/total on item/skill_cooldown updates.
//! Server membership comes from authored cooldown_tag_id, never a generic-tag lookup.
//! Shared state stays in the native tag list so one native tag reset clears the same
//! state on both sides. Expected bytes are literal native-reader fixtures, never
//! generated by a second encoder.

use std::sync::Arc;

use aaemu_commons::{Marshal, PacketStream};

use crate::data::GameData;
use crate::models::unit::{SkillAttribute, SkillModifier, UnitCooldowns, UnitModifierType};
use crate::net::registry::ClientPacket;
use crate::opcodes::sc;
use crate::server::GameServer;
use crate::systems::skills;
use crate::test_support::{open_client_skills, spawn_player, test_character, TestClient};
use crate::world::{now_ms, NpcRef, PlayerRef, WorldObject};

use skills::data::SkillTemplate;
use skills::handlers::{start_skill, CSStartSkillPacket};
use skills::packets::SCCooldownsPacket;
use skills::types::{skill_result, SkillCastTarget, SkillCaster, SkillObject};

const POTION: u32 = 11717;
const POTION_NEXT: u32 = 11720;
const FOOD: u32 = 11816;
const FOOD_NEXT: u32 = 11817;
const GLIDER: u32 = 13411;
const GLIDER_ZERO: u32 = 12373;
const UNTAGGED: u32 = 21001;

fn data() -> GameData {
    let mut data = GameData::empty();
    for (id, tag, duration) in [
        (POTION, 144, 60_000),
        // Deliberately different durations: use the started skill's duration for the group.
        (POTION_NEXT, 144, 3_000),
        (FOOD, 9, 3_000),
        (FOOD_NEXT, 9, 3_000),
        (GLIDER, 296, 10_000),
        (GLIDER_ZERO, 296, 0),
        (UNTAGGED, 0, 0),
    ] {
        data.systems.skills.add_skill(SkillTemplate {
            cooldown_tag_id: tag,
            cooldown_time: duration,
            mana_cost: 25,
            ..skills::tests::skill_template(id)
        });
    }
    // An unrelated generic tag must not become server cooldown-group membership.
    data.systems.skills.skill_tags.insert(UNTAGGED, vec![144]);
    data
}

fn fixture(mut data: GameData) -> (Arc<GameServer>, TestClient, PlayerRef, NpcRef) {
    open_client_skills(&mut data);
    let (server, mut client, player, npc) = skills::cast_validation_tests::fixture(data);
    client.conn.active_char = Some(player.clone());
    client.drain();
    (server, client, player, npc)
}

fn edit(data: &mut GameData, id: u32, change: impl FnOnce(&mut SkillTemplate)) {
    change(Arc::make_mut(
        data.systems.skills.skills.get_mut(&id).unwrap(),
    ));
}

fn cast(server: &GameServer, client: &mut TestClient, id: u32, target: u32) {
    let player = client.conn.active_char.clone().unwrap();
    {
        let mut p = player.data();
        // Isolate skill/tag cooldown admission from the existing per-press/GCD throttle.
        p.unit.skill_last_used_ms = 0;
        p.unit.global_cooldown_ms = 0;
    }
    // CS 1.2 caster/target unions: unit kind 0, 3-byte object ids (397C85B0/397C7A40).
    let mut request = Vec::from(id.to_le_bytes());
    request.push(0);
    request.extend_from_slice(&player.obj_id.to_le_bytes()[..3]);
    request.push(0);
    request.extend_from_slice(&target.to_le_bytes()[..3]);
    request.push(0);
    let packet = CSStartSkillPacket::read(&mut PacketStream::from_bytes(request)).unwrap();
    start_skill(server, &mut client.conn, packet);
}

type UiCooldownEntry = (u32, u32, u32);

/// Minimal native 397B2350/39899D40 reader and 3989A290 remaining-time lookup.
#[derive(Debug, Default)]
struct UiCooldowns {
    skills: Vec<UiCooldownEntry>,
    tags: Vec<UiCooldownEntry>,
}

impl UiCooldowns {
    fn read(bytes: &[u8]) -> Self {
        let mut body = PacketStream::from_bytes(bytes.to_vec());
        let mut read_list = || {
            let count = body.read_i32().unwrap();
            assert!((0..=150).contains(&count));
            (0..count)
                .map(|_| {
                    (
                        body.read_u32().unwrap(),
                        body.read_u32().unwrap(),
                        body.read_u32().unwrap(),
                    )
                })
                .collect::<Vec<_>>()
        };
        let skills = read_list();
        let tags = read_list();
        assert_eq!(bytes.len(), 8 + (skills.len() + tags.len()) * 12);
        Self { skills, tags }
    }

    fn remaining(&self, skill_id: u32, authored_tag: u32) -> u32 {
        self.skills
            .iter()
            .filter(|e| e.0 == skill_id)
            .chain(
                self.tags
                    .iter()
                    .filter(|e| authored_tag != 0 && e.0 == authored_tag),
            )
            .map(|e| e.2)
            .max()
            .unwrap_or(0)
    }

    /// Native 391D6420 -> 39899EC0/39899F00 clears the named record in each list.
    fn reset(&mut self, bytes: &[u8], unit_id: u32) {
        let mut body = PacketStream::from_bytes(bytes.to_vec());
        assert_eq!(body.read_bc().unwrap(), unit_id);
        let skill_id = body.read_u32().unwrap();
        let tag = body.read_u32().unwrap();
        assert!(!body.read_bool().unwrap());
        for (list, id) in [(&mut self.skills, skill_id), (&mut self.tags, tag)] {
            if let Some(entry) = list.iter_mut().find(|e| e.0 == id) {
                entry.2 = 0;
            }
        }
    }
}

fn cooldown_lists(frames: &[(u16, Vec<u8>)]) -> UiCooldowns {
    let packets: Vec<_> = frames
        .iter()
        .filter(|(op, _)| *op == sc::SCCooldownsPacket)
        .collect();
    assert_eq!(
        packets.len(),
        1,
        "one UI application per accepted tagged cast"
    );
    UiCooldowns::read(&packets[0].1)
}

fn assert_denied(frames: &[(u16, Vec<u8>)], result: u8) {
    assert!(!frames.iter().any(|(op, _)| *op == sc::SCSkillFiredPacket));
    assert!(!frames.iter().any(|(op, _)| *op == sc::SCCooldownsPacket));
    let errors: Vec<_> = frames
        .iter()
        .filter(|(op, _)| *op == sc::SCSkillStartedPacket)
        .collect();
    assert_eq!(errors.len(), 1);
    // Native 397CA290 -> 397B1EF0: the error byte follows the extra-flags byte at the end.
    assert_eq!(&errors[0].1[errors[0].1.len() - 2..], &[1, result]);
}

#[tokio::test]
async fn packet_flow_denies_never_used_member_and_preserves_long_individual_cooldown() {
    let (server, mut client, player, npc) = fixture(data());
    let long_end = now_ms() + 120_000;
    player
        .data()
        .unit
        .cooldowns
        .cooldowns
        .insert(POTION_NEXT, long_end);
    cast(&server, &mut client, POTION, npc.obj_id);
    let frames = client.drain();
    assert!(frames.iter().any(|(op, _)| *op == sc::SCSkillFiredPacket));
    let ui = cooldown_lists(&frames);
    assert_eq!(ui.skills.len(), 1);
    assert_eq!(ui.skills[0].0, POTION);
    assert_eq!(ui.tags.len(), 1);
    assert_eq!(ui.tags[0].0, 144);
    assert!(ui.remaining(POTION_NEXT, 144) <= 60_000);
    assert!(ui.remaining(POTION_NEXT, 144) > 59_000);
    assert!(!ui.skills.iter().any(|e| e.0 == POTION_NEXT));
    assert_eq!(
        player.data().unit.cooldowns.cooldowns[&POTION_NEXT],
        long_end
    );
    // Remove only the fixture's old individual cooldown: this member has never been cast.
    player.data().unit.cooldowns.remove_cooldown(POTION_NEXT);
    cast(&server, &mut client, POTION_NEXT, npc.obj_id);
    assert_denied(&client.drain(), skill_result::COOLDOWN_TIME);
    assert_eq!(player.data().unit.mp, 75);
    assert!(!player
        .data()
        .unit
        .cooldowns
        .cooldowns
        .contains_key(&POTION_NEXT));
}

#[tokio::test]
async fn native_start_update_bytes_keep_current_individual_separate_from_shared_expiry() {
    let (server, mut client, player, _) = fixture(data());
    {
        let mut p = player.data();
        p.unit.cooldowns.add_cooldown(POTION, 120_000, 1000);
        p.unit.cooldowns.add_tag_cooldown(144, 180_000, 1000);
    }
    let caster = WorldObject::from(&player);
    let skill = super::new_skill_for(
        &server,
        server
            .game_data
            .systems
            .skills
            .skill(POTION)
            .unwrap()
            .clone(),
        Some(&caster),
    );
    super::start_skill_cooldown(&server, &skill, &caster, 1000);
    let frames = client.drain();
    let packet = frames
        .iter()
        .find(|(op, _)| *op == sc::SCCooldownsPacket)
        .unwrap();
    // 397B2350: one skill (11717, 120000, 120000), then one tag (144, 180000, 180000).
    assert_eq!(
        packet.1,
        [
            1, 0, 0, 0, 0xc5, 0x2d, 0, 0, 0xc0, 0xd4, 1, 0, 0xc0, 0xd4, 1, 0, 1, 0, 0, 0, 0x90, 0,
            0, 0, 0x20, 0xbf, 2, 0, 0x20, 0xbf, 2, 0,
        ]
    );
    let ui = cooldown_lists(&frames);
    assert_eq!(ui.skills[0].2, 120_000);
    assert_eq!(ui.remaining(POTION, 144), 180_000);
    assert_eq!(player.data().unit.cooldowns.cooldowns[&POTION], 121_000);
    assert_eq!(player.data().unit.cooldowns.tag_cooldowns[&144], 181_000);
}

#[tokio::test]
async fn food_glider_zero_duration_members_and_players_have_independent_groups() {
    let (server, mut client, player, npc) = fixture(data());
    for (id, member, tag) in [
        (POTION, POTION_NEXT, 144),
        (FOOD, FOOD_NEXT, 9),
        (GLIDER, GLIDER_ZERO, 296),
    ] {
        player.data().unit.mp = 100;
        cast(&server, &mut client, id, npc.obj_id);
        let ui = cooldown_lists(&client.drain());
        assert_eq!(ui.skills.len(), 1);
        assert_eq!(ui.skills[0].0, id);
        assert_eq!(ui.tags.len(), 1);
        assert_eq!(ui.tags[0].0, tag);
        assert!(ui.remaining(member, tag) > 0);
    }
    cast(&server, &mut client, GLIDER_ZERO, npc.obj_id);
    assert_denied(&client.drain(), skill_result::COOLDOWN_TIME);
    player.data().unit.mp = 100;
    cast(&server, &mut client, UNTAGGED, npc.obj_id);
    assert!(client.drain_ops().contains(&sc::SCSkillFiredPacket));
    assert!(!player
        .data()
        .unit
        .cooldowns
        .cooldowns
        .contains_key(&UNTAGGED));
    let mut other = TestClient::new(&server, 2, 2);
    let mut c = test_character(2, "Other", 100.0, 100.0);
    c.unit.hp = 1000;
    c.unit.mp = 100;
    c.unit.max_mp = 1000;
    let other_player = spawn_player(&server, &other, c, 0x101);
    other.conn.active_char = Some(other_player.clone());
    other.drain();
    client.drain();
    cast(&server, &mut other, POTION_NEXT, npc.obj_id);
    assert_eq!(other_player.data().unit.mp, 75);
    let ui = cooldown_lists(&other.drain());
    assert_eq!(ui.skills.len(), 1);
    assert_eq!(ui.tags.len(), 1);
    assert!(!client.drain_ops().contains(&sc::SCCooldownsPacket));
}

#[tokio::test]
async fn untagged_skill_keeps_its_individual_cooldown_and_negative_tags_are_not_groups() {
    for tag in [0, -1] {
        let mut data = data();
        edit(&mut data, UNTAGGED, |s| {
            s.cooldown_time = 10_000;
            s.cooldown_tag_id = tag;
        });
        let (server, mut client, player, npc) = fixture(data);
        cast(&server, &mut client, UNTAGGED, npc.obj_id);
        assert!(client.drain_ops().contains(&sc::SCSkillFiredPacket));
        assert!(player.data().unit.cooldowns.tag_cooldowns.is_empty());
        cast(&server, &mut client, UNTAGGED, npc.obj_id);
        assert_denied(&client.drain(), skill_result::COOLDOWN_TIME);
        assert_eq!(player.data().unit.mp, 75);
    }
}

#[tokio::test]
async fn group_uses_started_skills_cooldown_modifier_and_expiry_allows_a_new_member() {
    let (server, mut client, player, npc) = fixture(data());
    player
        .data()
        .unit
        .skill_modifiers
        .add_modifiers(&[SkillModifier {
            id: 1,
            owner_id: 1,
            tag_id: 0,
            skill_attribute: SkillAttribute::Cooldown,
            unit_modifier_type: UnitModifierType::Percent,
            value: -50,
            skill_id: POTION,
            synergy: false,
        }]);
    cast(&server, &mut client, POTION, npc.obj_id);
    let ui = cooldown_lists(&client.drain());
    assert_eq!(ui.skills.len(), 1);
    assert_eq!(ui.tags.len(), 1);
    assert!(ui.remaining(POTION_NEXT, 144) > 29_000);
    assert!(ui.remaining(POTION_NEXT, 144) <= 30_000);
    player
        .data()
        .unit
        .cooldowns
        .tag_cooldowns
        .insert(144, now_ms() - 1);
    cast(&server, &mut client, POTION_NEXT, npc.obj_id);
    let ui = cooldown_lists(&client.drain());
    assert_eq!(ui.skills.len(), 1);
    assert_eq!(ui.skills[0].0, POTION_NEXT);
    assert!(ui.skills[0].2 <= 3_000);
    assert_eq!(ui.tags.len(), 1);
    assert!(ui.tags[0].2 <= 3_000);
    assert!(player.data().unit.cooldowns.cooldowns[&POTION] > now_ms() + 29_000);
    assert_eq!(player.data().unit.mp, 50);
}

#[tokio::test]
async fn cast_cost_failure_and_new_group_during_cast_do_not_start_cooldowns() {
    for group_started in [false, true] {
        let mut data = data();
        edit(&mut data, POTION_NEXT, |s| s.casting_time = 60_000);
        let (server, mut client, player, npc) = fixture(data);
        cast(&server, &mut client, POTION_NEXT, npc.obj_id);
        let task = player.data().unit.skill_state.skill_task.clone().unwrap();
        assert!(player.data().unit.cooldowns.cooldowns.is_empty());
        assert!(player.data().unit.cooldowns.tag_cooldowns.is_empty());
        assert_eq!(player.data().unit.mp, 100);
        client.drain();
        if group_started {
            player
                .data()
                .unit
                .cooldowns
                .add_tag_cooldown(144, 60_000, now_ms());
        } else {
            player.data().unit.mp = 0;
        }
        let before = player.data().unit.cooldowns.clone();
        super::cast(
            &server,
            &task.skill,
            &super::CastCtx {
                caster: WorldObject::from(&player),
                caster_caster: SkillCaster::Unit(player.obj_id),
                target: skills::geometry::Target::Obj(WorldObject::from(&npc)),
                target_caster: SkillCastTarget::Unit(npc.obj_id),
                skill_object: SkillObject::None,
            },
        );
        task.cancel.cancel();
        let frames = client.drain();
        assert!(!frames
            .iter()
            .any(|(op, _)| *op == sc::SCSkillFiredPacket || *op == sc::SCCooldownsPacket));
        assert_eq!(player.data().unit.cooldowns, before);
        assert_eq!(player.data().unit.mp, if group_started { 100 } else { 0 });
    }
}

#[tokio::test(start_paused = true)]
async fn channel_commits_cost_and_shared_cooldown_once_and_stop_keeps_them() {
    let mut data = data();
    edit(&mut data, FOOD, |s| s.channeling_time = 60_000);
    let (server, mut client, player, npc) = fixture(data);
    cast(&server, &mut client, FOOD, npc.obj_id);
    let ui = cooldown_lists(&client.drain());
    assert_eq!(ui.skills.len(), 1);
    assert_eq!(ui.tags.len(), 1);
    assert_eq!(player.data().unit.mp, 75);
    let task = player.data().unit.skill_state.skill_task.clone().unwrap();
    let before = player.data().unit.cooldowns.clone();
    super::stop(&server, &task.skill, &WorldObject::from(&player), 0);
    assert_eq!(player.data().unit.cooldowns, before);
    assert!(!client.drain_ops().contains(&sc::SCCooldownsPacket));
}

#[tokio::test]
async fn gm_override_bypasses_shared_admission_and_resets_the_native_tag() {
    let (server, mut client, player, npc) = fixture(data());
    player.data().skill_char.ignore_skill_cooldowns = true;
    for _ in 0..2 {
        cast(&server, &mut client, POTION, npc.obj_id);
        let frames = client.drain();
        assert!(frames.iter().any(|(op, _)| *op == sc::SCSkillFiredPacket));
        assert!(!frames.iter().any(|(op, _)| *op == sc::SCCooldownsPacket));
        let reset = frames
            .iter()
            .find(|(op, _)| *op == sc::SCSkillCooldownResetPacket)
            .unwrap();
        // Native 397B5770 / OnSkillCooldownReset 391D6420: bc chr, u32 skill/tag, bool gcd.
        assert_eq!(reset.1, [0, 1, 0, 0xc5, 0x2d, 0, 0, 0x90, 0, 0, 0, 0]);
    }
    assert_eq!(player.data().unit.mp, 50);
    assert!(player.data().unit.cooldowns.cooldowns.is_empty());
    assert!(player.data().unit.cooldowns.tag_cooldowns.is_empty());
    player
        .data()
        .unit
        .cooldowns
        .add_tag_cooldown(144, 60_000, now_ms());
    player.data().unit.mp = 100;
    cast(&server, &mut client, POTION_NEXT, npc.obj_id);
    assert!(client.drain_ops().contains(&sc::SCSkillFiredPacket));
}

#[tokio::test]
async fn gm_ignore_then_off_clears_the_same_native_records_and_preserves_longer_members() {
    let (server, mut client, player, npc) = fixture(data());
    let now = now_ms();
    {
        let mut p = player.data();
        let cds = &mut p.unit.cooldowns;
        cds.add_cooldown(POTION, 60_000, now);
        cds.add_cooldown(POTION_NEXT, 120_000, now);
        cds.add_cooldown(FOOD, 60_000, now);
        cds.add_tag_cooldown(144, 60_000, now);
        cds.add_tag_cooldown(9, 60_000, now);
    }
    let before = player.data().unit.cooldowns.clone();
    // Feed the UI actual encoded server bytes, including a longer individual timer.
    let initial = SCCooldownsPacket::from_cooldowns(&before, now);
    client.conn.send(&initial);
    let mut ui = cooldown_lists(&client.drain());
    assert_eq!(ui.remaining(POTION, 144), 60_000);
    assert_eq!(ui.remaining(POTION_NEXT, 144), 120_000);

    let mut other = TestClient::new(&server, 2, 2);
    let mut character = test_character(2, "Foreign", 100.0, 100.0);
    character.unit.cooldowns = before.clone();
    let foreign = spawn_player(&server, &other, character, 0x101);
    other.drain();
    client.drain();

    player.data().skill_char.ignore_skill_cooldowns = true;
    cast(&server, &mut client, POTION, npc.obj_id);
    let frames = client.drain();
    assert!(frames.iter().any(|(op, _)| *op == sc::SCSkillFiredPacket));
    assert!(!frames.iter().any(|(op, _)| *op == sc::SCCooldownsPacket));
    let resets: Vec<_> = frames
        .iter()
        .filter(|(op, _)| *op == sc::SCSkillCooldownResetPacket)
        .collect();
    assert_eq!(resets.len(), 1);
    // Literal native 397B5770 record: bc 0x100, skill 11717, tag 144, gcd false.
    assert_eq!(resets[0].1, [0, 1, 0, 0xc5, 0x2d, 0, 0, 0x90, 0, 0, 0, 0]);
    ui.reset(&resets[0].1, player.obj_id);
    player.data().skill_char.ignore_skill_cooldowns = false;
    assert!(
        now_ms() < before.tag_cooldowns[&144],
        "old shared expiry is still in the future"
    );
    assert_eq!(ui.remaining(POTION, 144), 0);
    assert_eq!(ui.remaining(POTION_NEXT, 144), 120_000);
    assert_eq!(ui.remaining(FOOD, 9), 60_000);
    {
        let p = player.data();
        let cds = &p.unit.cooldowns;
        assert!(!cds.cooldowns.contains_key(&POTION));
        assert!(!cds.tag_cooldowns.contains_key(&144));
        assert_eq!(cds.cooldowns[&POTION_NEXT], before.cooldowns[&POTION_NEXT]);
        assert_eq!(cds.cooldowns[&FOOD], before.cooldowns[&FOOD]);
        assert_eq!(cds.tag_cooldowns[&9], before.tag_cooldowns[&9]);
    }
    assert_eq!(foreign.data().unit.cooldowns, before);
    assert!(!other.drain_ops().contains(&sc::SCSkillCooldownResetPacket));

    // Ignore is off: the long member still refuses, while the reset skill can start
    // again before its original tag expiry, matching the UI's two native stores.
    cast(&server, &mut client, POTION_NEXT, npc.obj_id);
    assert_denied(&client.drain(), skill_result::COOLDOWN_TIME);
    cast(&server, &mut client, POTION, npc.obj_id);
    let frames = client.drain();
    assert!(frames.iter().any(|(op, _)| *op == sc::SCSkillFiredPacket));
    let update = cooldown_lists(&frames);
    assert_eq!(update.skills.len(), 1);
    assert_eq!(update.skills[0].0, POTION);
    assert_eq!(update.tags.len(), 1);
    assert_eq!(update.tags[0].0, 144);
}

#[tokio::test]
async fn controlled_unit_shared_cooldown_does_not_populate_owners_native_snapshot() {
    let (server, mut client, player, _) = fixture(data());
    let now = now_ms();
    player
        .data()
        .unit
        .cooldowns
        .add_tag_cooldown(9, 120_000, now);
    let owner_cooldowns = player.data().unit.cooldowns.clone();
    let mut data = crate::models::mate::Mate::new(1, 1);
    data.owner_obj_id = player.obj_id;
    let mate = crate::world::Entity::new(0x300, data);
    let caster = WorldObject::from(&mate);
    let skill = super::new_skill_for(
        &server,
        server
            .game_data
            .systems
            .skills
            .skill(POTION)
            .unwrap()
            .clone(),
        Some(&caster),
    );
    client.drain();
    super::start_skill_cooldown(&server, &skill, &caster, now);
    assert_eq!(mate.data().unit.cooldowns.cooldowns[&POTION], now + 60_000);
    assert_eq!(mate.data().unit.cooldowns.tag_cooldowns[&144], now + 60_000);
    assert!(mate
        .data()
        .unit
        .cooldowns
        .check_skill_cooldown(POTION_NEXT, 144, now));
    assert_eq!(player.data().unit.cooldowns, owner_cooldowns);
    // 391D43C0 imports this subject-less packet into the local character manager.
    assert!(!client.drain_ops().contains(&sc::SCCooldownsPacket));
}

#[tokio::test]
async fn gm_reset_targets_the_controlled_units_native_store_instead_of_its_owners() {
    let (server, mut client, player, _) = fixture(data());
    let now = now_ms();
    player.data().skill_char.ignore_skill_cooldowns = true;
    player
        .data()
        .unit
        .cooldowns
        .add_cooldown(POTION, 60_000, now);
    player
        .data()
        .unit
        .cooldowns
        .add_tag_cooldown(144, 60_000, now);
    let owner_cooldowns = player.data().unit.cooldowns.clone();
    let mut data = crate::models::mate::Mate::new(1, 1);
    data.owner_obj_id = player.obj_id;
    data.unit.cooldowns = owner_cooldowns.clone();
    let mate = crate::world::Entity::new(0x300, data);
    let caster = WorldObject::from(&mate);
    let skill = super::new_skill_for(
        &server,
        server
            .game_data
            .systems
            .skills
            .skill(POTION)
            .unwrap()
            .clone(),
        Some(&caster),
    );
    super::reset_cooldown_if_ignored(&server, &skill, &caster);
    let frames = client.drain();
    let reset = frames
        .iter()
        .find(|(op, _)| *op == sc::SCSkillCooldownResetPacket)
        .unwrap();
    // The owner receives the packet, but its bc subject is the mate, 0x300.
    assert_eq!(reset.1, [0, 3, 0, 0xc5, 0x2d, 0, 0, 0x90, 0, 0, 0, 0]);
    assert!(mate.data().unit.cooldowns.cooldowns.is_empty());
    assert!(mate.data().unit.cooldowns.tag_cooldowns.is_empty());
    assert_eq!(player.data().unit.cooldowns, owner_cooldowns);
}

#[tokio::test]
async fn npc_policy_keeps_accepting_server_skills_without_shortening_group_expiry() {
    let (server, _client, player, npc) = fixture(data());
    let caster = WorldObject::from(&npc);
    npc.data().unit.mp = 100;
    npc.data()
        .unit
        .cooldowns
        .add_tag_cooldown(144, 120_000, now_ms());
    let longer = npc.data().unit.cooldowns.tag_cooldowns[&144];
    for id in [POTION, POTION_NEXT] {
        let skill = super::new_skill_for(
            &server,
            server.game_data.systems.skills.skill(id).unwrap().clone(),
            Some(&caster),
        );
        assert_eq!(
            super::use_skill(
                &server,
                &skill,
                &caster,
                SkillCaster::Unit(npc.obj_id),
                &mut SkillCastTarget::Unit(player.obj_id),
                None,
                true
            )
            .0,
            skill_result::SUCCESS
        );
        assert_eq!(npc.data().unit.cooldowns.tag_cooldowns[&144], longer);
    }
}

#[tokio::test]
async fn select_snapshot_keeps_native_lists_and_preserves_long_individual_expiry() {
    let server = crate::test_support::test_server_with(data());
    let mut client = TestClient::new(&server, 1, 1);
    let now = now_ms();
    let mut character = test_character(1, "Restored", 100.0, 100.0);
    character.unit.cooldowns.add_tag_cooldown(144, 60_000, now);
    character
        .unit
        .cooldowns
        .add_cooldown(POTION_NEXT, 120_000, now);
    character
        .unit
        .cooldowns
        .add_tag_cooldown(9, 3_000, now - 10_000);
    crate::world::session::select_loaded(&server, &mut client.conn, character, Default::default())
        .unwrap();
    let ui = cooldown_lists(&client.drain());
    assert_eq!(ui.skills.len(), 1);
    assert_eq!(ui.skills[0].0, POTION_NEXT);
    assert_eq!(ui.tags.len(), 1);
    assert_eq!(ui.tags[0].0, 144);
    assert!(ui.remaining(POTION, 144) > 59_000);
    assert!(ui.remaining(POTION_NEXT, 144) > 119_000);
}

#[tokio::test]
async fn native_snapshot_bytes_use_longest_expiry_and_omit_expired_or_unrelated_members() {
    let mut cooldowns = UnitCooldowns::default();
    cooldowns.add_tag_cooldown(144, 60_000, 0);
    cooldowns.add_cooldown(POTION_NEXT, 120_000, 0);
    let packet = SCCooldownsPacket::from_cooldowns(&cooldowns, 1000);
    let mut body = PacketStream::new();
    packet.write(&mut body);
    assert_eq!(
        body.into_bytes(),
        [
            1, 0, 0, 0, 0xc8, 0x2d, 0, 0, 0xd8, 0xd0, 1, 0, 0xd8, 0xd0, 1, 0, 1, 0, 0, 0, 0x90, 0,
            0, 0, 0x78, 0xe6, 0, 0, 0x78, 0xe6, 0, 0,
        ]
    );
    assert_eq!(
        SCCooldownsPacket::from_cooldowns(&cooldowns, 120_000),
        Default::default()
    );
}

#[test]
fn native_snapshot_lists_are_sorted_capped_independently_and_expiry_safe() {
    let mut cds = UnitCooldowns::default();
    for id in (1..=152).rev() {
        cds.cooldowns.insert(id, 60_000);
        cds.tag_cooldowns.insert(id + 1000, 120_000);
    }
    cds.cooldowns.insert(0, 1000);
    cds.tag_cooldowns.insert(0, 1000);
    let packet = SCCooldownsPacket::from_cooldowns(&cds, 1000);
    assert_eq!(packet.skills.len(), 150);
    assert_eq!(packet.tags.len(), 150);
    assert_eq!(
        packet.skills.iter().map(|e| e.id).collect::<Vec<_>>(),
        (1..=150).collect::<Vec<_>>()
    );
    assert_eq!(
        packet.tags.iter().map(|e| e.id).collect::<Vec<_>>(),
        (1001..=1150).collect::<Vec<_>>()
    );
    let mut body = PacketStream::new();
    packet.write(&mut body);
    let ui = UiCooldowns::read(&body.into_bytes());
    assert_eq!(ui.skills.len(), 150);
    assert_eq!(ui.tags.len(), 150);
    assert_eq!(ui.remaining(1, 1001), 119_000);
    cds.cooldowns.clear();
    cds.tag_cooldowns.clear();
    cds.cooldowns.insert(POTION, i64::MAX);
    cds.tag_cooldowns.insert(144, i64::MAX);
    let packet = SCCooldownsPacket::from_cooldowns(&cds, i64::MIN);
    assert_eq!(packet.skills[0].remaining_ms, u32::MAX);
    assert_eq!(packet.tags[0].remaining_ms, u32::MAX);
}

#[tokio::test]
async fn zero_negative_and_overflow_durations_never_wrap_or_create_spurious_cooldowns() {
    for duration in [0, -1, i32::MIN] {
        let mut data = data();
        edit(&mut data, POTION, |s| s.cooldown_time = duration);
        let (server, mut client, player, npc) = fixture(data);
        cast(&server, &mut client, POTION, npc.obj_id);
        let frames = client.drain();
        assert!(frames.iter().any(|(op, _)| *op == sc::SCSkillFiredPacket));
        assert!(!frames.iter().any(|(op, _)| *op == sc::SCCooldownsPacket));
        assert!(player.data().unit.cooldowns.cooldowns.is_empty());
        assert!(player.data().unit.cooldowns.tag_cooldowns.is_empty());
    }
    let (server, _client, player, _) = fixture(data());
    player.data().unit.skill_modifiers.add_modifiers(&[
        SkillModifier {
            id: 1,
            owner_id: 1,
            tag_id: 0,
            skill_attribute: SkillAttribute::Cooldown,
            unit_modifier_type: UnitModifierType::Value,
            value: i32::MAX,
            skill_id: POTION,
            synergy: false,
        },
        SkillModifier {
            id: 2,
            owner_id: 2,
            tag_id: 0,
            skill_attribute: SkillAttribute::Cooldown,
            unit_modifier_type: UnitModifierType::Percent,
            value: i32::MAX,
            skill_id: POTION,
            synergy: false,
        },
    ]);
    let caster = WorldObject::from(&player);
    let skill = super::new_skill_for(
        &server,
        server
            .game_data
            .systems
            .skills
            .skill(POTION)
            .unwrap()
            .clone(),
        Some(&caster),
    );
    super::start_skill_cooldown(&server, &skill, &caster, 0);
    assert_eq!(
        player.data().unit.cooldowns.tag_cooldowns[&144],
        i64::from(u32::MAX)
    );
    player.data().unit.cooldowns = UnitCooldowns::default();
    super::start_skill_cooldown(&server, &skill, &caster, i64::MAX - 100);
    assert_eq!(player.data().unit.cooldowns.tag_cooldowns[&144], i64::MAX);
    let mut cds = UnitCooldowns::default();
    cds.add_tag_cooldown(144, 60_000, 0);
    cds.add_tag_cooldown(144, 1_000, 10);
    assert_eq!(cds.tag_cooldowns[&144], 60_000);
    assert!(cds.check_skill_cooldown(POTION_NEXT, 144, 59_749));
    assert!(!cds.check_skill_cooldown(POTION_NEXT, 144, 59_750));
    assert!(cds.tag_cooldowns.is_empty());
}

#[tokio::test]
async fn plot_end_keeps_modified_shared_expiry_nonnegative_and_sends_only_one_ui_update() {
    for duration in [60_000, 0, -1] {
        let mut data = data();
        edit(&mut data, POTION, |s| {
            s.plot_only = true;
            s.plot_id = Some(77);
            s.cooldown_time = duration;
        });
        let (server, mut client, player, npc) = fixture(data);
        player
            .data()
            .unit
            .skill_modifiers
            .add_modifiers(&[SkillModifier {
                id: 1,
                owner_id: 1,
                tag_id: 0,
                skill_attribute: SkillAttribute::Cooldown,
                unit_modifier_type: UnitModifierType::Percent,
                value: -50,
                skill_id: POTION,
                synergy: false,
            }]);
        cast(&server, &mut client, POTION, npc.obj_id);
        // Missing tree executes do_plot_end through the real scheduler without a cast path.
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while player.data().unit.skill_state.active_plot.is_some() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("plot reaches do_plot_end");
        let frames = client.drain();
        assert!(frames.iter().any(|(op, _)| *op == sc::SCPlotEndedPacket));
        if duration > 0 {
            let ui = cooldown_lists(&frames);
            assert_eq!(ui.skills.len(), 1);
            assert_eq!(ui.tags.len(), 1);
            assert!(ui.remaining(POTION_NEXT, 144) > 29_000);
            assert!(ui.remaining(POTION_NEXT, 144) <= 30_000);
            let cds = &player.data().unit.cooldowns;
            assert_eq!(cds.cooldowns[&POTION], cds.tag_cooldowns[&144]);
        } else {
            assert!(!frames.iter().any(|(op, _)| *op == sc::SCCooldownsPacket));
            assert!(player.data().unit.cooldowns.cooldowns.is_empty());
            assert!(player.data().unit.cooldowns.tag_cooldowns.is_empty());
        }
    }
}
